const UI_LOCALE_KEY = 'novel-studio:ui-locale'

export function readUiLocale(storage: Pick<Storage, 'getItem'>): UiLocale {
  const value = storage.getItem(UI_LOCALE_KEY)
  return supportedUiLocales.includes(value as UiLocale) ? value as UiLocale : DEFAULT_UI_LOCALE
}

export function getUiText(locale: UiLocale, key: UiTextKey): string {
  if (locale === 'en-US' && key === 'integrityFooter') return 'Only SQLite indexes are rebuilt; chapter text, Canon, Revision, and Workflow history remain unchanged.'
  if (key === 'candidates') return locale === 'zh-CN' ? '候选 P/S/R/M：{pinned}/{structured}/{recency}/{semantic}' : 'Candidates P/S/R/M: {pinned}/{structured}/{recency}/{semantic}'
  if (key in storeMessages) return storeMessages[key as keyof typeof storeMessages][locale]
  if (key in chatWorkspaceMessages) return chatWorkspaceMessages[key as keyof typeof chatWorkspaceMessages][locale]
  if (key in rightPanelMessages) return rightPanelMessages[key as keyof typeof rightPanelMessages][locale]
  if (key in welcomeMessages) return welcomeMessages[key as keyof typeof welcomeMessages][locale]
  if (key in authoringMessages) return authoringMessages[key as keyof typeof authoringMessages][locale]
  if (key in storyFormMessages) return storyFormMessages[key as keyof typeof storyFormMessages][locale]
  if (key in illustrationFormMessages) return illustrationFormMessages[key as keyof typeof illustrationFormMessages][locale]
  if (key in backupMessages) return backupMessages[key as keyof typeof backupMessages][locale]
  if (key in canonMessages) return canonMessages[key as keyof typeof canonMessages][locale]
  if (key in selectionMessages) return selectionMessages[key as keyof typeof selectionMessages][locale]
  if (key in checkpointMessages) return checkpointMessages[key as keyof typeof checkpointMessages][locale]
  if (key in editorMessages) return editorMessages[key as keyof typeof editorMessages][locale]
  if (key in artifactMessages) return artifactMessages[key as keyof typeof artifactMessages][locale]
  if (key in storyFeedbackMessages) return storyFeedbackMessages[key as keyof typeof storyFeedbackMessages][locale]
  if (key in illustrationMessages) return illustrationMessages[key as keyof typeof illustrationMessages][locale]
  if (key in illustrationReferenceMessages) return illustrationReferenceMessages[key as keyof typeof illustrationReferenceMessages][locale]
  if (key in communityWorkflowMessages) return communityWorkflowMessages[key as keyof typeof communityWorkflowMessages][locale]
  if (key in workflowEditorMessages) return workflowEditorMessages[key as keyof typeof workflowEditorMessages][locale]
  if (key in chatActionMessages) return chatActionMessages[key as keyof typeof chatActionMessages][locale]
  if (key in graphMessages) return graphMessages[key as keyof typeof graphMessages][locale]
  if (key in providerMessages) return providerMessages[key as keyof typeof providerMessages][locale]
  if (key in developerMessages) return developerMessages[key as keyof typeof developerMessages][locale]
  if (key in extensionInstallMessages) return extensionInstallMessages[key as keyof typeof extensionInstallMessages][locale]
  if (key in bottomPanelMessages) return bottomPanelMessages[key as keyof typeof bottomPanelMessages][locale]
  if (key in sceneMessages) return sceneMessages[key as keyof typeof sceneMessages][locale]
  if (key in sidebarMessages) return sidebarMessages[key as keyof typeof sidebarMessages][locale]
  if (key in commandMessages) return commandMessages[key as keyof typeof commandMessages][locale]
  if (key in commandActionMessages) return commandActionMessages[key as keyof typeof commandActionMessages][locale]
  if (key in updateMessages) return updateMessages[key as keyof typeof updateMessages][locale]
  if (key in notificationMessages) return notificationMessages[key as keyof typeof notificationMessages][locale]
  if (key in storyTimelineMessages) return storyTimelineMessages[key as keyof typeof storyTimelineMessages][locale]
  if (key in integrityMessages) return integrityMessages[key as keyof typeof integrityMessages][locale]
  return messages[locale][key as keyof typeof messages['zh-CN']]
}

export function persistUiLocale(storage: Pick<Storage, 'setItem'>, locale: UiLocale): void {
  storage.setItem(UI_LOCALE_KEY, locale)
}

const UI_LOCALE_EVENT = 'novel:ui-locale-changed'

export function useUiLocale(): readonly [UiLocale, (locale: UiLocale) => void] {
  const [locale, setLocale] = useState<UiLocale>(() => typeof localStorage === 'undefined' ? DEFAULT_UI_LOCALE : readUiLocale(localStorage))
  useEffect(() => {
    const onLocaleChange = () => setLocale(typeof localStorage === 'undefined' ? DEFAULT_UI_LOCALE : readUiLocale(localStorage))
    window.addEventListener(UI_LOCALE_EVENT, onLocaleChange)
    return () => window.removeEventListener(UI_LOCALE_EVENT, onLocaleChange)
  }, [])
  const update = (next: UiLocale) => {
    if (typeof localStorage !== 'undefined') persistUiLocale(localStorage, next)
    setLocale(next)
    window.dispatchEvent(new Event(UI_LOCALE_EVENT))
  }
  return [locale, update] as const
}

export function useUiText(): (key: UiTextKey) => string {
  const [locale] = useUiLocale()
  return (key: UiTextKey) => getUiText(locale, key)
}
